-- Semilla local de Activa GYE (generada por scripts/seed-sql.mjs; no editar a mano).
-- Lugares: 300 de src/data/mock/places.osm.json.
-- Se ejecuta después de las migraciones en `supabase db reset`.

begin;

-- Lugares (uuid determinístico desde el id OSM; osm_id guarda el original).
on conflict (id) do nothing;

on conflict do nothing;

-- CUENTAS LOCALES: NO se carga en la nube (solo lugares). Contraseñas de docs/entrega/CUENTAS-DE-PRUEBA.md.
-- El trigger on_auth_user_created crea el perfil; luego se fija el rol.
-- protect_role solo bloquea cuando hay sesión (auth.uid()); aquí no la hay, y además se permite explícitamente.
select set_config('activa.allow_role_change', 'on', true);

  raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change)
values ('00000000-0000-4000-8000-000000000001', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'admin@activagye.test',
  crypt('ActivaAdmin2026!', gen_salt('bf')), now(),
  '{"provider":"email","providers":["email"]}'::jsonb,
  '{"full_name":"Administración Activa GYE"}'::jsonb,
  now(), now(), '', '', '', '');

values (gen_random_uuid(), '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001',
  jsonb_build_object('sub', '00000000-0000-4000-8000-000000000001', 'email', 'admin@activagye.test', 'email_verified', true, 'phone_verified', false),
  'email', now(), now(), now());

  raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change)
values ('00000000-0000-4000-8000-000000000002', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'nutri@activagye.test',
  crypt('ActivaNutri2026!', gen_salt('bf')), now(),
  '{"provider":"email","providers":["email"]}'::jsonb,
  '{"full_name":"Nutricionista de prueba"}'::jsonb,
  now(), now(), '', '', '', '');

values (gen_random_uuid(), '00000000-0000-4000-8000-000000000002', '00000000-0000-4000-8000-000000000002',
  jsonb_build_object('sub', '00000000-0000-4000-8000-000000000002', 'email', 'nutri@activagye.test', 'email_verified', true, 'phone_verified', false),
  'email', now(), now(), now());

  raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change)
values ('00000000-0000-4000-8000-000000000003', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'usuario@activagye.test',
  crypt('ActivaUser2026!', gen_salt('bf')), now(),
  '{"provider":"email","providers":["email"]}'::jsonb,
  '{"full_name":"Usuario de prueba","birth_date":"2000-05-10"}'::jsonb,
  now(), now(), '', '', '', '');

values (gen_random_uuid(), '00000000-0000-4000-8000-000000000003', '00000000-0000-4000-8000-000000000003',
  jsonb_build_object('sub', '00000000-0000-4000-8000-000000000003', 'email', 'usuario@activagye.test', 'email_verified', true, 'phone_verified', false),
  'email', now(), now(), now());

update public.profiles set role = 'admin' where id = '00000000-0000-4000-8000-000000000001';
update public.profiles set role = 'nutricionista' where id = '00000000-0000-4000-8000-000000000002';
update public.profiles set goal = 'bajar_peso' where id = '00000000-0000-4000-8000-000000000003';


-- SEMANA GRATIS DEMO: paciente semana@activagye.test (ActivaSemana2026!). Solo local: seed.sql no se sube a la nube.
-- Ficha llena, semana asignada con assign_trial y los días 1–7 completados (con chequeo), para probar el muro de pago.
  raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change)
values ('00000000-0000-4000-8000-000000000004', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'semana@activagye.test',
  crypt('ActivaSemana2026!', gen_salt('bf')), now(),
  '{"provider":"email","providers":["email"]}'::jsonb,
  '{"full_name":"Paciente semana demo","birth_date":"1995-08-20"}'::jsonb,
  now(), now(), '', '', '', '');

values (gen_random_uuid(), '00000000-0000-4000-8000-000000000004', '00000000-0000-4000-8000-000000000004',
  jsonb_build_object('sub', '00000000-0000-4000-8000-000000000004', 'email', 'semana@activagye.test', 'email_verified', true, 'phone_verified', false),
  'email', now(), now(), now());

update public.profiles set sex = 'femenino', goal = 'bajar_peso' where id = '00000000-0000-4000-8000-000000000004';
  values ('00000000-0000-4000-8000-000000000004', 70.0, 165.0, 'bajar_peso', 'ligero', '{}');

-- assign_trial como la paciente (la base decide la plantilla; aquí: mujer de 30 años, IMC 25,7).
select set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000004', 'role', 'authenticated')::text, true);
set local role authenticated;
select public.assign_trial();
reset role;

-- Fechas pasadas: el día 1 empezó hace 7 días y el día 7 fue ayer. Todo completado, con chequeo cada día.
update public.trials set started_on = public.gye_today() - 7 where user_id = '00000000-0000-4000-8000-000000000004';
update public.trial_days set unlocked_on = public.gye_today() - (8 - day_number),
  completed_at = ((public.gye_today() - (8 - day_number)) + time '20:00') at time zone 'America/Guayaquil'
  where user_id = '00000000-0000-4000-8000-000000000004';
update public.trial_items set done_at = ((public.gye_today() - (8 - day_number)) + at_time) at time zone 'America/Guayaquil'
  where user_id = '00000000-0000-4000-8000-000000000004';
  select '00000000-0000-4000-8000-000000000004', public.gye_today() - (8 - n), 4, round((70.6 - n * 0.2)::numeric, 1), 6, null
  from generate_series(1, 7) as n;

select set_config('activa.allow_role_change', 'off', true);

commit;
